window.VO = [{"id":"c01","text":"You there, keep a hand on your wallet. There's a pickpocket at the east gate.","at":0.16,"t0":0.08,"t1":4.185},{"id":"c02","text":"Did you hear? There's a pickpocket at the east gate, everyone's saying it!","at":9.47,"t0":4.735,"t1":8.38},{"id":"c03","text":"East gate, saab. Pickpocket. Police are going there now.","at":18.06,"t0":9.03,"t1":12.375},{"id":"n01","text":"So where's the pickpocket?","at":26.35,"t0":13.175,"t1":14.62},{"id":"n02","text":"He's at the west gate, where he took a wallet in the very first second.","at":31.84,"t0":15.92,"t1":19.665},{"id":"n03","text":"And the warning was his.","at":40.33,"t0":20.165,"t1":21.475},{"id":"n04b","text":"So the three people who warned you were one man, three times.","at":44.75,"t0":22.375,"t1":25.56},{"id":"n05c","text":"They sounded like three witnesses, and not one of them had seen him,","at":52.72,"t0":26.36,"t1":29.885},{"id":"n05d","text":"but he'd seen every hand go to a pocket, yours too.","at":60.27,"t0":30.135,"t1":32.97},{"id":"n07","text":"So while the police ran east and grabbed the first man they saw running,","at":67.74,"t0":33.87,"t1":37.61},{"id":"n08b","text":"he walked back through every pocket he'd watched them touch.","at":75.46,"t0":37.73,"t1":40.57},{"id":"c04","text":"You there, keep a hand on your wallet.","at":85.74,"t0":42.87,"t1":44.76}];
